package cl.ipvg.georegistro;
import android.Manifest; import android.app.*; import android.content.pm.PackageManager; import android.location.Location; import android.os.Bundle; import android.widget.*; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.appcompat.app.AppCompatActivity; import androidx.core.content.ContextCompat; import com.google.android.gms.location.*; import com.google.firebase.firestore.FirebaseFirestore; import java.text.SimpleDateFormat; import java.util.*; 
public class RegistroActivity extends AppCompatActivity{
EditText t,d; Spinner s; TextView f,la,lo; double lat,lon; String fecha=""; FusedLocationProviderClient gps; FirebaseFirestore db;
ActivityResultLauncher<String[]> permiso=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->{if(Boolean.TRUE.equals(r.get(Manifest.permission.ACCESS_FINE_LOCATION))||Boolean.TRUE.equals(r.get(Manifest.permission.ACCESS_COARSE_LOCATION))) obtener(); else toast("Permiso de ubicación denegado.");});
protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_registro); t=findViewById(R.id.etTitulo);d=findViewById(R.id.etDescripcion);s=findViewById(R.id.spCategoria);f=findViewById(R.id.tvFecha);la=findViewById(R.id.tvLatitud);lo=findViewById(R.id.tvLongitud);gps=LocationServices.getFusedLocationProviderClient(this);db=FirebaseFirestore.getInstance();s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Accidente","Obstrucción","Daño","Otro"}));findViewById(R.id.btnFecha).setOnClickListener(v->fecha());findViewById(R.id.btnUbicacion).setOnClickListener(v->solicitar());findViewById(R.id.btnGuardar).setOnClickListener(v->guardar());}
void fecha(){Calendar c=Calendar.getInstance();new DatePickerDialog(this,(v,y,m,day)->{c.set(y,m,day);new TimePickerDialog(this,(v2,h,min)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);fecha=new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(c.getTime());f.setText("Fecha y hora: "+fecha);},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
void solicitar(){boolean a=ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED,b=ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;if(a||b)obtener();else permiso.launch(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION});}
void obtener(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED)return;gps.getLastLocation().addOnSuccessListener(x->{if(x!=null){lat=x.getLatitude();lon=x.getLongitude();la.setText(String.format(Locale.US,"Latitud: %.6f",lat));lo.setText(String.format(Locale.US,"Longitud: %.6f",lon));}else toast("No hay ubicación. Activa el GPS.");}).addOnFailureListener(e->toast("Error de GPS."));}
void guardar(){String ti=t.getText().toString().trim(),de=d.getText().toString().trim();if(ti.isEmpty()){t.setError("Obligatorio");return;}if(de.isEmpty()){d.setError("Obligatorio");return;}if(fecha.isEmpty()){toast("Selecciona fecha y hora.");return;}if(lat==0&&lon==0){toast("Obtén la ubicación.");return;}Incidencia i=new Incidencia(ti,de,s.getSelectedItem().toString(),fecha,lat,lon,new Date());db.collection("incidencias").add(i).addOnSuccessListener(x->{toast("Guardado correctamente.");finish();}).addOnFailureListener(e->toast("No se pudo guardar. Revisa Firebase/Internet."));}
void toast(String x){Toast.makeText(this,x,Toast.LENGTH_LONG).show();}}